using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Default options with the reflection-based resolver — knows about any type.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip using the typed metadata
var json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing: TryGetTypeInfo returns false if the type isn't resolvable.
//    Here we use an options instance with NO resolver, so nothing is resolvable.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null   // no resolver → can't resolve anything
};
emptyOptions.MakeReadOnly();  // must be frozen before querying

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed))
{
    Console.WriteLine($"Unexpectedly resolved: {probed!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo returned false — no metadata available (no exception thrown).");
}

// Contrast: the full options DO resolve it.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"TryGetTypeInfo succeeded for: {found!.Type.Name}");
}

public record Person(string Name, int Age);

